namespace sv_9336d349e794436890832561896fdb2e.Models;

// Service contracts
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models for two-way binding
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

@namespace sv_9336d349e794436890832561896fdb2e.Components.JobApplication

<nav class="step-indicator" aria-label="Application progress">
    @for (var i = 0; i < Steps.Count; i++)
    {
        var stepIndex = i;
        var isActive = stepIndex == CurrentStep;
        var isCompleted = CompletedSteps.Contains(stepIndex);
        var cssClass = isActive ? "step active" : isCompleted ? "step completed" : "step";

        <button class="@cssClass"
                disabled="@(!isCompleted)"
                @onclick="() => OnStepClicked.InvokeAsync(stepIndex)"
                aria-current="@(isActive ? "step" : null)">
            <span class="step-number">
                @if (isCompleted)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@Steps[stepIndex]</span>
        </button>

        @if (stepIndex < Steps.Count - 1)
        {
            <span class="step-connector @(isCompleted ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public IReadOnlyList<string> Steps { get; set; } = [];
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0.5rem;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step.active {
    opacity: 1;
}

.step.completed {
    opacity: 1;
    cursor: pointer;
}

.step.completed:hover .step-number {
    background: #1a7f37;
}

.step-number {
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    background: #6c757d;
    color: white;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    transition: background 0.2s;
}

.step.active .step-number {
    background: #0d6efd;
}

.step.completed .step-number {
    background: #198754;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    font-size: 0.78rem;
    white-space: nowrap;
    color: #333;
}

.step.active .step-label {
    font-weight: 600;
    color: #0d6efd;
}

.step-connector {
    width: 2.5rem;
    height: 2px;
    background: #dee2e6;
    margin-bottom: 1.4rem;
    flex-shrink: 0;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

@namespace sv_9336d349e794436890832561896fdb2e.Components.JobApplication
@using sv_9336d349e794436890832561896fdb2e.Models

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">✕ Remove</button>
    }

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" @bind="Entry.Company" @bind:event="oninput" placeholder="Company name" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" @bind="Entry.Title" @bind:event="oninput" placeholder="Job title" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" @bind="Entry.StartDate" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" @bind="Entry.IsCurrent" @bind:after="OnCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea @bind="Entry.Description" @bind:event="oninput" rows="3" placeholder="Describe your responsibilities and achievements"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void OnCurrentChanged()
    {
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

@namespace sv_9336d349e794436890832561896fdb2e.Components.JobApplication
