@namespace sv_9336d349e794436890832561896fdb2e.Components.JobApplication

<nav class="step-indicator" aria-label="Application progress">
    @for (var i = 0; i < Steps.Count; i++)
    {
        var stepIndex = i;
        var isActive = stepIndex == CurrentStep;
        var isCompleted = CompletedSteps.Contains(stepIndex);
        var cssClass = isActive ? "step active" : isCompleted ? "step completed" : "step";

        <button class="@cssClass"
                disabled="@(!isCompleted)"
                @onclick="() => OnStepClicked.InvokeAsync(stepIndex)"
                aria-current="@(isActive ? "step" : null)">
            <span class="step-number">
                @if (isCompleted)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@Steps[stepIndex]</span>
        </button>

        @if (stepIndex < Steps.Count - 1)
        {
            <span class="step-connector @(isCompleted ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public IReadOnlyList<string> Steps { get; set; } = [];
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

