@namespace sv_9336d349e794436890832561896fdb2e.Components.JobApplication
@using sv_9336d349e794436890832561896fdb2e.Models

<div class="step-content">
    <h2>Review &amp; Submit</h2>

    @if (_submitted)
    {
        <div class="confirmation">
            <h3>🎉 Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>#@_applicationId</strong>.</p>
            <p>We'll be in touch soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="validation-errors"><p>@_error</p></div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-item">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span class="text-muted">
                        @entry.StartDate?.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-item">
                    <strong>@r.Name</strong> — @r.Relationship
                    <br />
                    <span class="text-muted">@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"• {r.Phone}" : "")</span>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        <div class="step-buttons">
            <button class="btn-outline" @onclick="OnBack">← Back</button>
            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_submitting">
                @(_submitting ? "Submitting…" : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool _submitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        _submitting = true;
        _error = null;

        try
        {
            _applicationId = await OnSubmit();
            _submitted = true;
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _submitting = false;
        }
    }
}

