@page "/apply"
@rendermode InteractiveServer
@using sv_9336d349e794436890832561896fdb2e.Components.JobApplication
@using sv_9336d349e794436890832561896fdb2e.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator Steps="_stepNames"
                   CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;

        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;

        case 2:
            <ReferencesStep References="_references"
                            OnNext="NextStep"
                            OnBack="PrevStep" />
            break;

        case 3:
            <CoverLetterStep @bind-CoverLetter="_coverLetter"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;

        case 4:
            <ReviewStep Personal="_personalInfo"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="PrevStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private static readonly List<string> _stepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private int _currentStep;
    private readonly HashSet<int> _completedSteps = [];

    // Form state
    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new WorkEntryModel()];
    private readonly List<ReferenceModel> _references = [new ReferenceModel(), new ReferenceModel()];
    private string _coverLetter = "";

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        if (_currentStep < _stepNames.Count - 1)
        {
            _currentStep++;
        }
    }

    private void PrevStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
        }
    }

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step))
        {
            _currentStep = step;
        }
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
            new WorkHistory(_workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-page {
    max-width: 720px;
    margin: 0 auto;
    padding: 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 0.5rem;
}

/* Shared form styles */
::deep .step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.5rem;
}

::deep .step-content h2 {
    margin-top: 0;
    margin-bottom: 1rem;
    font-size: 1.3rem;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.5rem;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
    font-size: 0.9rem;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="tel"],
::deep .form-group input[type="date"],
::deep .form-group textarea {
    width: 100%;
    padding: 0.5rem 0.7rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

::deep .form-group input:focus,
::deep .form-group textarea:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

::deep .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

::deep .checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.3rem;
    font-size: 0.85rem;
    cursor: pointer;
}

::deep .checkbox-label input[type="checkbox"] {
    width: auto;
}

::deep .validation-errors {
    background: #fef2f2;
    border: 1px solid #fca5a5;
    border-radius: 4px;
    padding: 0.7rem 1rem;
    margin-bottom: 1rem;
    color: #b91c1c;
    font-size: 0.9rem;
}

::deep .validation-errors p {
    margin: 0.2rem 0;
}

::deep .hint {
    font-size: 0.82rem;
    color: #6b7280;
    font-style: italic;
}

/* Buttons */
::deep .step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

::deep .btn-primary {
    background: #0d6efd;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-outline {
    background: white;
    color: #333;
    border: 1px solid #ced4da;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

::deep .btn-outline:hover {
    background: #f8f9fa;
}

::deep .btn-secondary {
    background: #f8f9fa;
    color: #333;
    border: 1px solid #ced4da;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

::deep .btn-secondary:hover {
    background: #e9ecef;
}

::deep .btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

::deep .btn-link:hover {
    color: #0b5ed7;
}

::deep .btn-submit {
    padding: 0.7rem 2rem;
    font-size: 1.05rem;
}

::deep .btn-remove {
    float: right;
    background: none;
    border: none;
    color: #dc3545;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .btn-remove:hover {
    text-decoration: underline;
}

/* Fieldset styling */
::deep fieldset {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
}

::deep fieldset legend {
    font-weight: 600;
    font-size: 0.95rem;
    padding: 0 0.4rem;
    color: #4b5563;
}

/* Character count */
::deep .char-count {
    display: block;
    text-align: right;
    font-size: 0.82rem;
    color: #6b7280;
    margin-top: 0.3rem;
}

::deep .char-count.warning {
    color: #d97706;
    font-weight: 600;
}

/* Review step */
::deep .review-section {
    margin-bottom: 1.5rem;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1rem;
}

::deep .review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

::deep .review-header h3 {
    margin: 0;
    font-size: 1.05rem;
}

::deep .review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

::deep .review-section dt {
    font-weight: 600;
    color: #6b7280;
    font-size: 0.9rem;
}

::deep .review-section dd {
    margin: 0;
    font-size: 0.9rem;
}

::deep .review-item {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
    font-size: 0.9rem;
}

::deep .review-item:last-child {
    border-bottom: none;
}

::deep .text-muted {
    color: #6b7280;
    font-size: 0.85rem;
}

::deep .cover-letter-preview {
    white-space: pre-wrap;
    background: #f9fafb;
    padding: 0.8rem;
    border-radius: 4px;
    font-size: 0.9rem;
    margin: 0;
}

::deep .confirmation {
    text-align: center;
    padding: 2rem 1rem;
}

::deep .confirmation h3 {
    font-size: 1.5rem;
    margin-bottom: 0.5rem;
}

