@page "/apply"
@rendermode InteractiveServer
@using sv_9336d349e794436890832561896fdb2e.Components.JobApplication
@using sv_9336d349e794436890832561896fdb2e.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator Steps="_stepNames"
                   CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;

        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;

        case 2:
            <ReferencesStep References="_references"
                            OnNext="NextStep"
                            OnBack="PrevStep" />
            break;

        case 3:
            <CoverLetterStep @bind-CoverLetter="_coverLetter"
                             OnNext="NextStep"
                             OnBack="PrevStep" />
            break;

        case 4:
            <ReviewStep Personal="_personalInfo"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="PrevStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private static readonly List<string> _stepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    private int _currentStep;
    private readonly HashSet<int> _completedSteps = [];

    // Form state
    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new WorkEntryModel()];
    private readonly List<ReferenceModel> _references = [new ReferenceModel(), new ReferenceModel()];
    private string _coverLetter = "";

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        if (_currentStep < _stepNames.Count - 1)
        {
            _currentStep++;
        }
    }

    private void PrevStep()
    {
        if (_currentStep > 0)
        {
            _currentStep--;
        }
    }

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step))
        {
            _currentStep = step;
        }
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(_personalInfo.FullName, _personalInfo.Email, _personalInfo.Phone, _personalInfo.Address),
            new WorkHistory(_workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate!.Value, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

